{"path":"services.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Services</title>
  <meta name="description" content="Integrative care options and a practical Session Planner to shape focus days and ongoing support.">
  <style>
    :root{--bg:#fbfbfb;--card:#ffffff;--accent:#0b6b5f;--muted:#6b7280;--glass:rgba(11,107,95,0.06);--radius:12px;--maxw:980px}
    *{box-sizing:border-box}
    html,body{height:100%}body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,"Helvetica Neue",Arial;line-height:1.45;color:#0f1724;background:var(--bg);-webkit-font-smoothing:antialiased}
    header{background:linear-gradient(180deg,rgba(11,107,95,0.06),transparent);border-bottom:1px solid rgba(15,23,36,0.04)}
    .wrap{max-width:var(--maxw);margin:0 auto;padding:36px 24px}
    nav{display:flex;gap:18px;align-items:center}
    nav a{color:var(--muted);text-decoration:none;font-weight:600;font-size:14px}
    nav a.logo{font-size:18px;color:var(--accent)}
    .hero{display:flex;gap:28px;align-items:center;justify-content:space-between}
    .hero .lead{max-width:58%}
    h1{margin:0 0 8px;font-size:28px;color:#082227}
    p.lead{margin:0;color:var(--muted)}
    .cta{display:inline-block;background:var(--accent);color:#fff;padding:10px 16px;border-radius:10px;text-decoration:none;font-weight:700}
    main{padding:28px 24px}
    .grid{display:grid;grid-template-columns:1fr 360px;gap:22px;max-width:var(--maxw);margin:0 auto}
    .card{background:var(--card);border-radius:var(--radius);padding:18px;box-shadow:0 6px 18px rgba(7,9,12,0.04)}
    .service-list{display:grid;gap:12px}
    .service{padding:12px;border-radius:10px;border:1px solid rgba(7,9,12,0.04)}
    .service h3{margin:0 0 6px;font-size:16px}
    .muted{color:var(--muted);font-size:14px}
    footer{max-width:var(--maxw);margin:36px auto;padding:12px 24px;color:var(--muted);font-size:13px}

    /* pattern background via data URI (unique SVG) */
    body::before{content:"";position:fixed;inset:0;background-image:url('data:image/svg+xml;utf8,<svg xmlns="http://www.w3.org/2000/svg" width="400" height="400" viewBox="0 0 400 400"><defs><linearGradient id="g" x1="0" x2="1"><stop offset="0" stop-color="%230b6b5f" stop-opacity="0.06"/><stop offset="1" stop-color="%230b6b5f" stop-opacity="0.02"/></linearGradient><pattern id="p" width="200" height="200" patternUnits="userSpaceOnUse"><rect width="200" height="200" fill="none"/><path d="M0 100 C50 60 150 140 200 100" stroke="%230b6b5f" stroke-opacity="0.03" stroke-width="2" fill="none"/></pattern></defs><rect width="100%" height="100%" fill="url(%23p)" /><circle cx="60" cy="60" r="34" fill="url(%23g)"/></svg>');background-repeat:repeat;opacity:1;pointer-events:none;z-index:0}
    .page{position:relative;z-index:1}

    /* reveal animation */
    [data-reveal]{opacity:0;transform:translateY(14px);transition:opacity .6s ease,transform .6s ease}
    [data-reveal].revealed{opacity:1;transform:none}

    /* small screens */
    @media (max-width:900px){.grid{grid-template-columns:1fr}.hero .lead{max-width:100%}}
  </style>
</head>
<body>
  <header>
    <div class="wrap page">
      <nav aria-label="Main navigation">
        <a class="logo" href="index.html">{{BUSINESS_NAME}}</a>
        <a href="services.html">Offerings</a>
        <a href="conditions.html">Concerns</a>
        <a href="approach.html">Our Method</a>
        <a href="pricing.html">Investment</a>
        <a href="about.html">Team</a>
        <a href="book.html">Book</a>
        <a href="contact.html">Reach</a>
      </nav>
      <div class="hero" style="margin-top:18px">
        <div class="lead" data-reveal>
          <h1>Focused days & sustainable supports for whole-life health</h1>
          <p class="lead muted">High-attention sessions, practical sequences, and a VIP-Day option for people who want a concentrated plan and trustworthy next steps.</p>
          <p style="margin-top:12px;"><a class="cta" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a></p>
        </div>
        <div class="card" data-reveal>
          <strong style="display:block;margin-bottom:8px">Quick contact</strong>
          <div class="muted">Call or text: <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
          <div class="muted">Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
        </div>
      </div>
    </div>
  </header>

  <main class="page">
    <section class="wrap grid" aria-labelledby="services-title">
      <div>
        <h2 id="services-title" data-reveal>Offerings built around busy lives</h2>
        <p class="muted" data-reveal>Choose between intensive planning sessions, ongoing integrative coaching, and focused clinical reviews that respect context and the evidence behind options.</p>

        <div class="card" style="margin-top:16px" data-reveal>
          <div class="service-list">
            <div class="service">
              <h3>VIP Focus Day</h3>
              <div class="muted">A dedicated full-day with a multidisciplinary lens: assessment, prioritized plan, and a tailored 60-day roadmap.</div>
              <div style="margin-top:8px;font-weight:700;color:var(--accent)">Investment starting at $2,400 — custom scopes available</div>
            </div>
            <div class="service">
              <h3>Foundational Series</h3>
              <div class="muted">Three-session learning and activation series that builds practical routines (nutrition + sleep + movement foundations).</div>
              <div style="margin-top:8px;font-weight:700;color:var(--accent)">Packages from $560 for 3 sessions</div>
            </div>
            <div class="service">
              <h3>Clinical Review & Synthesis</h3>
              <div class="muted">Deep review of records, labs, and current treatments with clear, evidence-aware options for next steps.</div>
              <div style="margin-top:8px;font-weight:700;color:var(--accent)">One-off review $320</div>
            </div>
            <div class="service">
              <h3>Maintenance & Coaching</h3>
              <div class="muted">Monthly blocks for coaching, medication checks, and iterative plan refinement without redundancy.</div>
              <div style="margin-top:8px;font-weight:700;color:var(--accent)">Ongoing retainer from $240/month</div>
            </div>
          </div>
        </div>

        <section style="margin-top:18px" data-reveal>
          <h3>How pricing works</h3>
          <p class="muted">Pricing is transparent and scoped to needs: some people need a single concentrated day; others prefer short cycles. We design the work to match capacity and goals rather than a one-size plan.</p>
        </section>

      </div>

      <aside>
        <div class="card" data-reveal>
          <strong>Session Planner</strong>
          <p class="muted">Try a short interactive planner to see what a focused plan might look like for you.</p>

          <div style="margin-top:10px">
            <label class="muted" for="goal">Primary goal</label>
            <input id="goal" type="text" placeholder="e.g., sleep regularity, reduce overwhelm" style="width:100%;margin-top:6px;padding:8px;border-radius:8px;border:1px solid rgba(7,9,12,0.06)">
          </div>

          <div style="margin-top:10px;display:grid;grid-template-columns:1fr 1fr;gap:8px">
            <div>
              <label class="muted" for="sessions">Planned sessions</label>
              <select id="sessions" style="width:100%;margin-top:6px;padding:8px;border-radius:8px;border:1px solid rgba(7,9,12,0.06)">
                <option>1 (one focused day)</option>
                <option>3 (short series)</option>
                <option>6 (quarter)</option>
              </select>
            </div>
            <div>
              <label class="muted" for="time">Weekly time</label>
              <select id="time" style="width:100%;margin-top:6px;padding:8px;border-radius:8px;border:1px solid rgba(7,9,12,0.06)">
                <option>15–30 min</option>
                <option>30–60 min</option>
                <option>60+ min</option>
              </select>
            </div>
          </div>

          <div style="margin-top:10px">
            <label class="muted" for="preference">Focus area</label>
            <select id="preference" style="width:100%;margin-top:6px;padding:8px;border-radius:8px;border:1px solid rgba(7,9,12,0.06)">
              <option>Sleep & circadian</option>
              <option>Energy & metabolism</option>
              <option>Stress, mood & nervous system</option>
              <option>Digestive and micro-nutrition</option>
            </select>
          </div>

          <div style="display:flex;gap:8px;margin-top:12px">
            <button id="build" style="flex:1;padding:10px;border-radius:8px;border:none;background:var(--accent);color:#fff;font-weight:700">Build plan</button>
            <button id="clear" style="flex:1;padding:10px;border-radius:8px;border:1px solid rgba(7,9,12,0.06);background:transparent">Reset</button>
          </div>

          <textarea id="summary" readonly style="width:100%;height:140px;margin-top:12px;padding:10px;border-radius:8px;border:1px solid rgba(7,9,12,0.06);font-family:monospace"></textarea>

          <div style="display:flex;gap:8px;margin-top:8px">
            <button id="copy" style="flex:1;padding:10px;border-radius:8px;border:none;background:#172554;color:#fff">Copy</button>
            <button id="download" style="flex:1;padding:10px;border-radius:8px;border:1px solid rgba(7,9,12,0.06);background:transparent">Download</button>
          </div>
        </div>

        <div class="card" style="margin-top:12px" data-reveal>
          <strong>Have a dedicated day in mind?</strong>
          <p class="muted">Reserve a VIP Focus Day to get an actionable roadmap and prioritized next steps.</p>
          <a class="cta" href="book.html">Reserve a Focus Day</a>
        </div>
      </aside>

    </section>
  </main>

  <footer>
    <div class="wrap">© {{BUSINESS_NAME}} — Serving {{CITY}}, {{STATE}} • <a href="contact.html">Contact</a></div>
  </footer>

  <script>
    (function(){
      // prefers-reduced-motion: disable reveal animation if set
      const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      function revealInit(){
        const items = document.querySelectorAll('[data-reveal]');
        if(reduced){ items.forEach(el=>el.classList.add('revealed')); return }
        const io = new IntersectionObserver((entries, obs)=>{
          entries.forEach(e=>{
            if(e.isIntersecting){ e.target.classList.add('revealed'); obs.unobserve(e.target) }
          })
        },{threshold:0.12});
        items.forEach(i=>io.observe(i));
      }
      document.addEventListener('DOMContentLoaded',revealInit);

      // Session Planner logic
      function buildSummary(){
        const goal = document.getElementById('goal').value.trim() || 'No primary goal provided';
        const sessions = document.getElementById('sessions').value;
        const time = document.getElementById('time').value;
        const pref = document.getElementById('preference').value;
        const lines = [];
        lines.push('Session Planner — {{BUSINESS_NAME}}');
        lines.push('Primary goal: ' + goal);
        lines.push('Planned format: ' + sessions + ' | Weekly time: ' + time);
        lines.push('Focus: ' + pref);
        lines.push('');
        lines.push('Suggested structure:');
        if(sessions.includes('1')){
          lines.push('- Single concentrated day: intake, prioritized 30/60-day roadmap, and clear next-step checklist.');
        } else if(sessions.includes('3')){
          lines.push('- Three sessions: assessment + targeted interventions + activation + simple measurement plan.');
        } else {
          lines.push('- Multi-session cycle: iterative adjustments, monthly checkpoints, and progressive habit layering.');
        }
        lines.push('- Early wins: 1–2 achievable actions in the first week; low-burden measurement (sleep log, step count, symptom note).');
        lines.push('- Safety & review: medication and lab review before major changes; plan a clinical review if needed.');
        lines.push('');
        lines.push('Next steps: Book an exploratory visit or request a clinical review.');
        return lines.join('\n');
      }

      document.getElementById('build').addEventListener('click', function(){
        document.getElementById('summary').value = buildSummary();
      });
      document.getElementById('clear').addEventListener('click', function(){
        document.getElementById('goal').value='';document.getElementById('summary').value='';
      });
      document.getElementById('copy').addEventListener('click', function(){
        const txt = document.getElementById('summary').value;
        if(!txt) return;
        if(navigator.clipboard){ navigator.clipboard.writeText(txt).then(()=>{alert('Plan copied to clipboard')}).catch(()=>{alert('Copy failed')}); }
        else{ const ta = document.createElement('textarea'); ta.value=txt; document.body.appendChild(ta); ta.select(); try{ document.execCommand('copy'); alert('Plan copied') }catch(e){alert('Copy not supported')} ta.remove(); }
      });
      document.getElementById('download').addEventListener('click', function(){
        const txt = document.getElementById('summary').value || buildSummary();
        const blob = new Blob([txt],{type:'text/plain'}); const url = URL.createObjectURL(blob);
        const a=document.createElement('a'); a.href=url; a.download='session-plan.txt'; document.body.appendChild(a); a.click(); a.remove(); URL.revokeObjectURL(url);
      });
    })();
  </script>
</body>
</html>"} 
