  <script>
    (function(){
      // reveal logic
      const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      function initReveal(){
        const items = document.querySelectorAll('[data-reveal]');
        if(reduced){ items.forEach(i=>i.classList.add('revealed')); return }
        const io = new IntersectionObserver((entries,obs)=>{
          entries.forEach(e=>{ if(e.isIntersecting){ e.target.classList.add('revealed'); obs.unobserve(e.target) } })
        },{threshold:0.08});
        items.forEach(i=>io.observe(i));
      }
      document.addEventListener('DOMContentLoaded',initReveal);

      // Planner
      function make(){
        const goal = document.getElementById('a-goal').value.trim() || 'No goal provided';
        const sessions = document.getElementById('a-sessions').value;
        const focus = document.getElementById('a-focus').value;
        const arr = [];
        arr.push('Plan — {{BUSINESS_NAME}}');
        arr.push('Goal: ' + goal);
        arr.push('Format: ' + sessions + ' | Focus: ' + focus);
        arr.push('');
        arr.push('Week 1:');
        arr.push('- Intake & baseline measures (sleep log, symptom notes, simple biometrics)');
        arr.push('- One small experiment: e.g., fixed bedtime and a short evening wind-down');
        arr.push('Week 2:');
        arr.push('- Review data, keep what works, adjust timing');
        arr.push('- Add second small habit (morning anchor or light exposure)');
        arr.push('Review at session: set next 2 actionable priorities and how they will be measured.');
        return arr.join('\n');
      }
      document.getElementById('a-build').addEventListener('click', function(){ document.getElementById('a-summary').value = make(); });
      document.getElementById('a-copy').addEventListener('click', function(){ const t=document.getElementById('a-summary').value; if(!t) return; if(navigator.clipboard){ navigator.clipboard.writeText(t).then(()=>alert('Copied plan')) }else{ alert('Copy not supported in this browser') } });
    })();
  </script>
